files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #eaeaea;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #1a5fb4;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  color: var(--vt-ink-soft);
  background: var(--vt-surface);
  line-height: 1.6;
}

.root .container {
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.root .nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--vt-surface);
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
  padding: 10px 0;
}

.root .navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.root .navGroup {
  display: flex;
  gap: 1.5rem;
}

.root .navLink {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  transition: color 0.3s;
  padding: 0.5rem 0;
}

.root .navLink:hover,
.root .navLink:focus-visible {
  color: var(--vt-ink);
}

.root .logo {
  flex: 0 0 auto;
  margin: 0 1.5rem;
  text-decoration: none;
}

.root .brand {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--vt-accent);
}

.root .brand strong {
  display: block;
  font-size: 0.75rem;
  color: var(--vt-ink-soft);
  font-weight: 400;
}

.root .hero {
  position: relative;
  height: 580px;
  overflow: hidden;
}

.root .heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  position: absolute;
  inset: 0;
  -webkit-overflow-scrolling: touch;
}

.root .heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
}

.root .heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.root .heroCard {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  z-index: 2;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.1);
}

.root .heroTitle {
  font-size: 3rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
}

.root .heroText {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
  font-size: 1.1rem;
}

.root .heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.root .customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  margin-right: 1rem;
  text-decoration: none;
  text-transform: uppercase;
  overflow: hidden;
  position: relative;
}

.root .customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  transition: top 0.3s;
  text-align: center;
}

.root .customLink:hover::before {
  top: 0;
}

.root .contactPhone {
  font-weight: 600;
  margin: 0;
}

.root .about {
  padding: 7rem 0;
  background: var(--vt-surface);
}

.root .sectionTitle {
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
  text-align: center;
}

.root .sectionText {
  font-size: 1.1rem;
  color: var(--vt-ink-soft);
  max-width: 800px;
  margin: 0 auto;
  line-height: 1.8;
}

.root .gallery {
  background: var(--vt-surface-2);
}

.root .galleryGrid {
  display: flex;
  flex-wrap: wrap;
}

.root .galleryItem {
  flex: 0 0 50%;
  margin: 0;
  overflow: hidden;
}

.root .galleryItem img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
}

.root .timeline {
  padding: 7rem 0;
  background: var(--vt-surface);
  position: relative;
}

.root .timelineGrid {
  position: relative;
}

.root .timelineGrid::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 1px;
  background: var(--vt-line);
  transform: translateX(-50%);
}

.root .timelineNode {
  display: flex;
  align-items: flex-start;
  margin-bottom: 3rem;
  position: relative;
}

.root .timelineNode.even {
  flex-direction: row;
}

.root .timelineNode.odd {
  flex-direction: row-reverse;
}

.root .timelineIcon {
  flex: 0 0 80px;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  position: relative;
  margin: 0 2rem;
}

.root .timelineIcon span {
  font-size: 2rem;
  color: var(--vt-accent);
}

.root .timelineContent {
  flex: 1;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.1);
  border-radius: 0.25rem;
  overflow: hidden;
}

.root .timelineHeading {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  font-size: 1.5rem;
  font-weight: 600;
  position: relative;
}

.root .timelineNode.even .timelineHeading::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineNode.odd .timelineHeading::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineText {
  padding: 20px 30px;
  color: var(--vt-ink-soft);
}

.root .footer {
  background: var(--vt-surface-2);
  padding: 5rem 0;
}

.root .footerGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 2rem;
}

.root .footerHeading {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.root .copyright {
  text-align: center;
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
}

@media (max-width: 991px) {
  .root .hero {
    height: auto;
  }
  .root .heroTrack {
    position: static;
    height: 400px;
  }
  .root .heroCard {
    position: relative;
    width: auto;
    bottom: auto;
    right: auto;
    margin-top: -100px;
    margin-bottom: 0;
    padding: 2rem;
  }
  .root .navIn {
    flex-wrap: wrap;
    justify-content: center;
  }
  .root .logo {
    margin: 0 1rem;
  }
  .root .navGroup {
    gap: 1rem;
  }
  .root .footerGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 767px) {
  .root .timelineGrid::before {
    left: 33px;
  }
  .root .timelineNode.even,
  .root .timelineNode.odd {
    flex-direction: column;
    align-items: flex-start;
    padding-left: 80px;
  }
  .root .timelineIcon {
    position: absolute;
    left: 0;
    top: 0;
  }
  .root .timelineContent {
    width: 100%;
  }
  .root .timelineNode.even .timelineHeading::after,
  .root .timelineNode.odd .timelineHeading::after {
    display: none;
  }
}
